public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();

    permuteHelper(new ArrayList<>(), nums, permutations);

    return permutations;
}

private void permuteHelper(List<Integer> currentPermutation, int[] nums, List<List<Integer>> permutations) {
    if (currentPermutation.size() == nums.length) {
        permutations.add(new ArrayList<>(currentPermutation));
        return;
    }

    for (int i = 0; i < nums.length; i++) {
        if (currentPermutation.contains(nums[i])) {
            continue;
        }

        currentPermutation.add(nums[i]);
        permuteHelper(currentPermutation, nums, permutations);
        currentPermutation.remove(currentPermutation.size() - 1);
    }
}

public int findLargestSubstring(List<String> strings) {
	// Find the largest string in the list
	String largestString = Collections.max(strings);

	// Get the length of the largest string
	int largestStringLength = largestString.length();

	// Initialize the largest substring length to 0
	int largestSubstringLength = 0;

	// Iterate over the strings in the list
	for (String string : strings) {
		// Check if either the largest string or its inverse is a substring of the current string
		if (string.contains(largestString) || string.contains(largestString.reverse())) {
			// Get the length of the substring that contains either the largest string or its inverse
			int substringLength = string.indexOf(largestString + largestString.reverse());

			// Update the largest substring length if the current substring length is larger
			largestSubstringLength = Math.max(largestSubstringLength, substringLength);
