public int search(int[] nums, int target) {
    // Find the pivot index
    int pivot = findPivot(nums, target);

    // Check if the target is in the left or right subarray
    if (pivot > 0 && nums[pivot - 1] == target) {
        return pivot - 1;
    } else if (pivot < nums.length - 1 && nums[pivot + 1] == target) {
        return pivot + 1;
    }

    // Search in the left or right subarray
    int left = 0, right = nums.length - 1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (nums[mid] == target) {
            return mid;
        } else if (nums[mid] > target) {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

    // Not found
    return -1;
}

private int findPivot(int[] nums, int target) {
    // Check if the target is in the left or right subarray
    if (nums[0] == target) {
        return 0;
    } else if (nums[nums.length - 1] == target) {
        return nums.length - 1;
    }

    // Search in the left or right subarray
    int left = 0, right = nums.length - 1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (nums[mid] == target) {
            return mid;
        } else if (nums[mid] > target) {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

    // Not found
    return -1;
}

public double trimMean(int[] arr) {
