    Arrays.sort(arr);

    // Calculate the indices of the 5% smallest and largest elements
    int smallestIndex = (int) (arr.length * 0.05);
    int largestIndex = arr.length - smallestIndex;

    // Calculate the sum of the remaining elements
    double sum = 0;
    for (int i = smallestIndex; i < largestIndex; i++) {
        sum += arr[i];
