    return pairs.size() == k / arr.length;
  }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Check if the input parameters are valid
  if (n < 0 || edges.length != n - 1 || hasApple.length != n) {
    throw new IllegalArgumentException("Invalid input parameters");
  }

  // Create an array to keep track of the visited nodes
  boolean[] visited = new boolean[n];

  // Create a Queue to store the nodes to visit
  Queue<Integer> queue = new ArrayDeque<Integer>();

  // Add node 0 to the queue
  queue.offer(0);

  // Keep track of the minimum time
  int minTime = 0;

  while (!queue.isEmpty()) {
    // Get the node at the front of the queue
    int node = queue.poll();

    // If the node has not been visited before, visit it and add its neighbors to the queue
    if (!visited[node]) {
      visited[node] = true;
      for (int neighbor : edges[node]) {
        if (!visited[neighbor]) {
          queue.offer(neighbor);
        }
      }
    }

    // If the node has an apple and it is not the starting node, add its time to the minimum time
    if (hasApple[node] && node != 0) {
      minTime += node;
    }
  }

  // Return the minimum time
  return minTime;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    boolean[] used = new boolean[s.length()];

    // step 1
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (!used[i]) {
            result.append(c);
            used[i] = true;
        }
    }

    // step 2
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (used[i]) continue;
        int j = i;
        while (j < s.length() && s.charAt(j) > c) {
            j++;
        }
        if (j < s.length()) {
            result.append(s.charAt(j));
            used[j] = true;
        }
    }

    // step 3
    for (int i = s.length() - 1; i >= 0; i--) {
        char c = s.charAt(i);
        if (used[i]) continue;
        int j = i;
        while (j >= 0 && s.charAt(j) < c) {
            j--;
        }
        if (j >= 0) {
            result.insert(0, s.charAt(j));
            used[j] = true;
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
