public int minOperations(int n) {
  int[] arr = new int[n];
  for (int i = 0; i < n; i++) {
    arr[i] = (2 * i) + 1;
  }

  int minOps = 0;
  while (!isEqual(arr)) {
    int x = minIndex(arr);
    int y = maxIndex(arr);
    arr[x] -= 1;
    arr[y] += 1;
    minOps++;
  }

  return minOps;
}

private boolean isEqual(int[] arr) {
  for (int i = 0; i < arr.length - 1; i++) {
    if (arr[i] != arr[i + 1]) {
