  return true;
}

private int minIndex(int[] arr) {
  int min = Integer.MAX_VALUE;
  int minIndex = -1;
  for (int i = 0; i < arr.length; i++) {
    if (arr[i] < min) {
      min = arr[i];
      minIndex = i;
    }
  }
  return minIndex;
}

private int maxIndex(int[] arr) {
