public int findMinFibonacciNumbers(int k) {
    // Initialize the Fibonacci sequence
    int f1 = 1, f2 = 1, fn = 0;

    // Loop until the sum of the Fibonacci sequence is greater than or equal to k
    while (f1 + f2 < k) {
        fn = f1 + f2;
        f1 = f2;
        f2 = fn;
    }

    // Count the number of Fibonacci numbers in the sequence
    int count = 0;
    while (fn > 0) {
        count++;
        fn = fn - f1;
    }

    return count;
}

public int kthFactor(int n, int k) {
