                    current++;
                }
                max = Math.max(max, current);
            }
        }
    }

    return max;
}

public static String addThousandSeparator(int n) {
    // Check if the input is valid
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }

    // Create a string builder to build the output string
    StringBuilder sb = new StringBuilder();

    // Add the thousands marker '.' after every three digits
    for (int i = 0; i < n.length(); i++) {
        sb.append(n.charAt(i));
        if (i > 0 && i % 3 == 0) {
            sb.append('.');
        }
    }

    // Return the final string with thousand separators added
    return sb.toString();
}

public static int squarePermutations(int[] A) {
    Set<Integer> permutations = new HashSet<>();
    permutations.add(0);
    for (int i = 0; i < A.length; i++) {
        int sum = 0;
        for (int j = i - 1; j < i + 2; j++) {
            if (j < 0 || j >= A.length) {
                continue;
            }
            sum += A[j];
        }
        if (sum * sum == A[i]) {
            permutations.add(i);
        }
    }
    return permutations.size();
}

public static int largestRectangleArea(int[] heights) {
    // Initialize variables
    int maxArea = 0;
    int currentArea = 0;
    int i = 0;
    int j = 0;

    // Loop through the heights array from left to right
    while (i < heights.length) {
        // Find the first index where the height is 0
        while (i < heights.length && heights[i] == 0) {
            i++;
        }

        // If we reached the end of the array, return the max area
        if (i == heights.length) {
            return maxArea;
        }

        // Initialize the current area with the height of the first non-zero height bar
        currentArea = heights[i];
        j = i + 1;

        // Loop through the remaining heights from the current index
        while (j < heights.length) {
            // If the current height is greater than the current area, update the area
            if (heights[j] > currentArea) {
                currentArea = heights[j];
            }

            // If the current height is less than or equal to the current area,
            // we can calculate the area of the rectangle and update the max area
            if (heights[j] <= currentArea) {
                maxArea = Math.max(maxArea, currentArea * (j - i + 1));
                i = j + 1;
                break;
            }

            j++;
        }
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int[] result = new int[mat.length * mat.length];
    int row = 0, col = 0;
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat.length - i; j++) {
            result[row++] = mat[i][j];
        }
        row--;
        col++;
        for (int j = mat.length - 1; j > i; j--) {
            result[row++] = mat[i][j];
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    // Check if n is positive
    if (n <= 0) {
        return -1;
    }

    // Get the number of digits in n
    int numDigits = (int)Math.log10(n) + 1;

    // Create an array to store the digits of n
    int[] digits = new int[numDigits];

    // Get the digits of n and store them in the array
    for (int i = 0; i < numDigits; i++) {
        digits[i] = n % 10;
        n /= 10;
    }

    // Sort the digits in descending order
    Arrays.sort(digits, Collections.reverseOrder());

    // Create a string builder to store the rearranged digits
    StringBuilder sb = new StringBuilder();

    // Append the digits to the string builder in the correct order
    for (int i = 0; i < numDigits; i++) {
        sb.append(digits[i]);
    }

    // Parse the string builder to an integer
    int rearrangedInteger = Integer.parseInt(sb.toString());

    // Check if the rearranged integer is greater than n
    if (rearrangedInteger > n) {
        return rearrangedInteger;
    } else {
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n < 1) return Collections.emptyList();

    // Create a list to store the center symmetric numbers
    List<String> result = new ArrayList<>();

    // Generate the numbers for the odd length cases first
    for (int i = 1; i < n; i += 2) {
        int num = (int) Math.pow(10, i - 1) + (int) Math.pow(10, i);
        result.add(Integer.toString(num));
    }

    // If n is even, generate the numbers for the even length cases
    if (n % 2 == 0) {
        int num = (int) Math.pow(10, n / 2 - 1) + (int) Math.pow(10, n / 2);
        result.add(Integer.toString(num));
    }

    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length < 3) {
        return false;
    }

    int a = points[0][0] - points[1][0];
    int b = points[1][1] - points[2][1];
    int c = points[2][0] - points[1][0];
    int d = points[1][1] - points[0][1];
    return a * d == b * c;
}

public int findNthUglyNumber(int N) {
    if (N <= 0)
        throw new IllegalArgumentException("N must be a positive integer");

    int[] factors = new int[4]; // prime factors 2, 3, 5, and 7
    factors[0] = 1; // initialize the first ugly number

    for (int i = 1; i < N; i++) {
        factors[0]++; // increment the factor for the current ugly number

        // calculate the next ugly number by multiplying the current factors
        int product = 1;
        for (int j = 0; j < factors.length; j++) {
            product *= factors[j];
        }

        // add the next ugly number to the list
        factors[0] = product;
    }

    // return the nth ugly number
    return factors[0];
}

