        }

        int maxLength = 0;
        int currentLength = 0;
        char currentChar = s.charAt(0);

        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) == currentChar) {
                currentLength++;
            } else {
                if (currentLength > maxLength) {
                    maxLength = currentLength;
                }
                currentLength = 0;
            }
        }

        if (currentLength > maxLength) {
            maxLength = currentLength;
        }

        return maxLength;
    }

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    result.sort((a, b) -> {
        String strA = Integer.toString(a);
        String strB = Integer.toString(b);
        int length = Math.min(strA.length(), strB.length());
        for (int i = 0; i < length; i++) {
            if (strA.charAt(i) != strB.charAt(i)) {
                return strA.charAt(i) - strB.charAt(i);
            }
        }
        return strA.length() - strB.length();
    });
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    Set<Integer> seen = new HashSet<>();
    for (int num : nums) {
        if (!seen.contains(num)) {
            sum += num;
            seen.add(num);
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
  int count = 0;
  for (int i = 1; i <= n; i++) {
    int root = (int)Math.sqrt(i);
    if (root * root == i) {
      count++;
    }
  }
  return count;
}

public static String reverseWords(String s) {
    // Check if input string is empty
    if (s.isEmpty()) {
        return "";
    }

    // Split input string into an array of words
    String[] words = s.split(" ");

    // Initialize result string
    StringBuilder result = new StringBuilder();

    // Iterate through each word and reverse its characters
    for (int i = 0; i < words.length; i++) {
        // Reverse word characters
        String word = new StringBuilder(words[i]).reverse().toString();

        // Add word to result
        result.append(word);

        // Add space if not last word
        if (i < words.length - 1) {
            result.append(" ");
        }
    }

    return result.toString();
}
